2135	function Read-CodexConfigSubset {
2136	    param([string]$Path)
2137	    $tables = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([StringComparer]::Ordinal)
2138	    $result = [pscustomobject]@{ Path = $Path; Exists = $false; Ok = $true; Reason = ''; Tables = $tables }
2139	    $top = Get-TomlTable -Tables $tables -Segments @()
2140	    if (-not $Path -or -not (Test-Path -LiteralPath $Path)) { return $result }
2141	    $result.Exists = $true
2142	    $text = $null
2143	    try {
2144	        if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw 'it is not a file' }
2145	        $fs = New-Object System.IO.FileStream($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, ([System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete))
2146	        try {
2147	            $sr = New-Object System.IO.StreamReader($fs, $script:Utf8NoBom, $true)
2148	            try { $text = $sr.ReadToEnd() } finally { $sr.Dispose() }
2149	        } finally { $fs.Dispose() }
2150	    } catch {
2151	        $result.Ok = $false
2152	        $result.Reason = "the Codex config '$Path' could not be read: $(ConvertTo-OneLine $_.Exception.Message)"
2153	        return $result
2154	    }
2155	    if ($text.Length -gt 0 -and $text[0] -eq [char]0xFEFF) { $text = $text.Substring(1) }
2156	    $s = $text -replace "`r`n", "`n"
2157	    $lines = $s -split "`n"
2158	    $len = $s.Length
2159	    $i = 0
2160	    $line = 1
2161	    $current = $top
2162	    while ($i -lt $len) {
2163	        $i += $script:TomlRe.Ws.Match($s, $i).Length
2164	        if ($i -ge $len) { break }
2165	        $c = $s[$i]
2166	        if ($c -eq [char]"`n") { $i++; $line++; continue }
2167	        if ($c -eq [char]'#') { $i += $script:TomlRe.Comment.Match($s, $i).Length; continue }
2168	        $lineNo = $line
2169	        $lineText = $lines[$lineNo - 1]
2170	        $lineStart = 0
2171	        if ($i -gt 0) { $lineStart = $s.LastIndexOf([char]"`n", $i - 1) + 1 }
2172	        $fatal = "unsupported TOML construct at line ${lineNo}: $(Format-TomlLineForMessage -Line $lineText)"
2173	        if ($c -eq [char]'[') {
2174	            $isAot = ($i + 1 -lt $len -and $s[$i + 1] -eq [char]'[')
2175	            $close = if ($isAot) { ']]' } else { ']' }
2176	            $kp = Read-TomlKeyPath -S $s -Start ($i + $close.Length)
2177	            if (-not $kp -or $kp.End + $close.Length -gt $len -or $s.Substring($kp.End, $close.Length) -ne $close) {
2178	                $result.Ok = $false; $result.Reason = $fatal; break
2179	            }
2180	            $eol = Get-TomlLineEnd -S $s -Start ($kp.End + $close.Length)
2181	            if ($eol -lt 0) { $result.Ok = $false; $result.Reason = $fatal; break }
2182	            $t = Get-TomlTable -Tables $tables -Segments $kp.Segments
2183	            if ($isAot) { Set-TomlUnsupported $t "$fatal (array of tables)" }
2184	            elseif ($t.HeaderLine -gt 0) { Set-TomlUnsupported $t "table [$($t.Name)] is defined twice in the Codex config (lines $($t.HeaderLine) and $lineNo)" }
2185	            if ($t.HeaderLine -eq 0) { $t.HeaderLine = $lineNo }
2186	            $current = $t
2187	            $i = $eol
2188	            continue
2189	        }
2190	        $kp = Read-TomlKeyPath -S $s -Start $i
2191	        if (-not $kp -or $kp.End -ge $len -or $s[$kp.End] -ne [char]'=') { $result.Ok = $false; $result.Reason = $fatal; break }
2192	        $p = $kp.End + 1
2193	        $p += $script:TomlRe.Ws.Match($s, $p).Length
2194	        $v = Read-TomlValue -S $s -Start $p
2195	        if ($v.Error) { $result.Ok = $false; $result.Reason = "$fatal ($($v.Error))"; break }
2196	        $eol = Get-TomlLineEnd -S $s -Start $v.End
2197	        if ($eol -lt 0) { $result.Ok = $false; $result.Reason = $fatal; break }
2198	        $line += $v.Lines
2199	        $i = $eol
2200	        $construct = "unsupported TOML construct at line ${lineNo}: $(Format-TomlLineForMessage -Line $lineText -ValueStart ($p - $lineStart))"
2201	        $segs = @($kp.Segments)
2202	        if ($segs.Count -gt 1) {
2203	            $targetSegs = @($current.Segments) + @($segs[0..($segs.Count - 2)])
2204	            $target = Get-TomlTable -Tables $tables -Segments $targetSegs
2205	            Set-TomlUnsupported $target "$construct (dotted key)"
2206	            if (-not $current.Entries.ContainsKey($segs[0])) {
2207	                $current.Entries[$segs[0]] = [pscustomobject]@{ Key = $segs[0]; Line = $lineNo; Kind = 'dotted key'; Value = $null; Supported = $false; Reason = "$construct (dotted key)" }
2208	            }
2209	            continue
2210	        }
2211	        $k = [string]$segs[0]
2212	        if ($current.Entries.ContainsKey($k)) {
2213	            Set-TomlUnsupported $current "key '$k' is defined twice in [$($current.Name)] of the Codex config (lines $($current.Entries[$k].Line) and $lineNo)"
2214	            continue
2215	        }
2216	        $why = ''
2217	        if (-not $v.Supported) { $why = "$construct ($($v.Kind))" }
2218	        $current.Entries[$k] = [pscustomobject]@{ Key = $k; Line = $lineNo; Kind = $v.Kind; Value = $v.Value; Supported = $v.Supported; Reason = $why }
2219	        if ($v.Kind -eq 'array' -or $v.Kind -eq 'inline table') {
2220	            $sub = Get-TomlTable -Tables $tables -Segments (@($current.Segments) + @($k))
2221	            Set-TomlUnsupported $sub $why
2222	        }
2223	    }
2224	    return $result
2225	}
