2239	function Get-ProviderNames {
2240	    param($Config)
2241	    $names = New-Object System.Collections.Generic.List[string]
2242	    foreach ($t in $Config.Tables.Values) {
2243	        if (@($t.Segments).Count -eq 2 -and $t.Segments[0] -ceq 'model_providers') { $names.Add($t.Segments[1]) }
2244	    }
2245	    return , $names.ToArray()
2246	}
