2248	# [model_providers.<Name>]: { Found; Ok; Reason; Table }. Usable only when every key in
2249	# it is plain and nothing else writes into it (dotted keys, inline tables, sub-tables).
2250	function Get-ProviderTable {
2251	    param($Config, [string]$Name)
2252	    $key = (@('model_providers', $Name) -join $script:TomlKeySep)
2253	    if (-not $Config.Tables.ContainsKey($key)) {
2254	        # Declared only below its own path (a dotted key or header writing
2255	        # model_providers.<name>.x): the provider exists, but not as a plain table.
2256	        $prefix = $key + $script:TomlKeySep
2257	        foreach ($other in $Config.Tables.Values) {
2258	            if ((@($other.Segments) -join $script:TomlKeySep).StartsWith($prefix, [StringComparison]::Ordinal)) {
2259	                $why = $other.Reason
2260	                if (-not $why) { $why = "unsupported TOML construct at line $($other.HeaderLine): [$($other.Name)] declares the provider only through a sub-table" }
2261	                return [pscustomobject]@{ Found = $true; Ok = $false; Reason = $why; Table = $null }
2262	            }
2263	        }
2264	        return [pscustomobject]@{ Found = $false; Ok = $false; Reason = ''; Table = $null }
2265	    }
2266	    $t = $Config.Tables[$key]
2267	    $why = ''
2268	    if (-not $t.Ok) { $why = $t.Reason }
2269	    if (-not $why) {
2270	        foreach ($e in $t.Entries.Values) { if (-not $e.Supported) { $why = $e.Reason; break } }
2271	    }
2272	    if (-not $why) {
2273	        $prefix = $key + $script:TomlKeySep
2274	        foreach ($other in $Config.Tables.Values) {
2275	            if ((@($other.Segments) -join $script:TomlKeySep).StartsWith($prefix, [StringComparison]::Ordinal)) {
2276	                $why = $other.Reason
2277	                if (-not $why) { $why = "unsupported TOML construct at line $($other.HeaderLine): [$($other.Name)] (a sub-table of the provider)" }
2278	                break
2279	            }
2280	        }
2281	    }
2282	    return [pscustomobject]@{ Found = $true; Ok = (-not $why); Reason = $why; Table = $t }
2283	}
2284	
2285	# Can the scanner establish whether model_providers.<Name> is declared at all? '' = yes
2286	# (it is a plain table, or nothing declares it); otherwise the reason. A TOML value at key
2287	# path P only defines keys below P, so what can hide a declaration of
2288	# model_providers.<Name> is a construct at `model_providers` itself (an inline table,
2289	# array or string value; a dotted key `model_providers.<x> = ...` written from the top
2290	# level; an array of tables; a table defined twice) or an entry <Name> inside a
2291	# [model_providers] table that is not a sub-table header (an inline table, a dotted key,
2292	# a multi-line string, even a plain value). A construct under model_providers.<other>
2293	# cannot declare <Name> and does not count.
2294	function Get-ProviderSetProblem {
2295	    param($Config, [string]$Name)
2296	    $top = $Config.Tables['']
2297	    # (a top-level dotted key model_providers.<x>... is judged by the table it writes
2298	    # into, which the scanner marked: [model_providers] itself, or <x>'s table)
2299	    if ($top -and $top.Entries.ContainsKey('model_providers') -and $top.Entries['model_providers'].Kind -ne 'dotted key') {
2300	        $e = $top.Entries['model_providers']
2301	        $why = $e.Reason
2302	        if (-not $why) { $why = "model_providers at line $($e.Line) is a $($e.Kind), not a table of providers" }
2303	        return $why
2304	    }
2305	    if ($Config.Tables.ContainsKey('model_providers')) {
2306	        $mp = $Config.Tables['model_providers']
2307	        if (-not $mp.Ok) { return $mp.Reason }
2308	        if ($mp.Entries.ContainsKey($Name)) {
2309	            $e = $mp.Entries[$Name]
2310	            $why = $e.Reason
2311	            if (-not $why) { $why = "[model_providers] declares $Name at line $($e.Line) as a $($e.Kind), not as a table" }
2312	            return $why
2313	        }
2314	    }
2315	    return ''
2316	}
