2379	# The reviewer this run will talk to, as Codex will resolve it:
2380	#   provider  -Provider, else the config's model_provider, else 'openai' (Codex default)
2381	#   model     -Model, else the config's model
2382	#   endpoint  any provider with a [model_providers.<name>] table: its base_url and
2383	#             wire_api (Get-ProviderEndpoint). openai WITHOUT such a table: built in,
2384	#             'cc-provider-v1|builtin:openai', plus '|base_url=<canonical>' when
2385	#             OPENAI_BASE_URL (honoured by Codex for its built-in provider) is set.
2386	#             A user-defined [model_providers.openai] table is used for the identity
2387	#             when it is usable (whether Codex merges it over the built-in is not
2388	#             verified - the table is the safer claim, and it is noted in
2389	#             identity_note); an unusable one leaves the identity unresolved.
2390	#             provider_fingerprint = SHA-256 of that canonical string: comments, key
2391	#             order, whitespace, `name`, headers and secret rotation never change it.
2392	# Resolved = provider, model and endpoint all known and no profile in play; otherwise
2393	# Fingerprint is '' (such a run is never a parent) and Note says why (Note may also
2394	# carry information on a resolved identity). Error is set only for an explicit
2395	# -Provider that cannot be used (the caller refuses the run).
2396	function Resolve-ReviewerIdentity {
2397	    param($Config, [string]$Provider = '', [string]$Model = '', [string]$OpenAiBaseUrl = '', [string]$Engine = 'codex', [string]$Launcher = '', [string]$Auth = '', $Endpoint = $null)
2398	    $notes = New-Object System.Collections.Generic.List[string]
2399	    $id = [pscustomobject]@{
2400	        Provider       = 'unknown'
2401	        ProviderSource = ''
2402	        Model          = 'unknown'
2403	        ModelSource    = 'unknown'
2404	        Lineage        = ''
2405	        Resolved       = $false
2406	        Note           = ''
2407	        Error          = ''
2408	        Fingerprint    = ''
2409	        CompatString   = ''
2410	        HostName       = ''
2411	        BaseUrl        = ''
2412	        WireApi        = ''
2413	        ProviderConfig = (New-Object PSObject)
2414	        Display        = 'endpoint unknown'
2415	        ConfigPath     = [string]$Config.Path
2416	        Engine         = 'codex'
2417	        Auth           = ''
2418	        Endpoint       = $null
2419	    }
2420	    # Another engine than codex (Resolve-EngineIdentity): no Codex config lookup at all.
2421	    if ($Engine -and $Engine -ne 'codex') { return (Resolve-EngineIdentity -Identity $id -Engine $Engine -Provider $Provider -Model $Model -Launcher $Launcher -Auth $Auth -Endpoint $Endpoint) }
2422	    $where = if ($Config.Path) { [string]$Config.Path } else { '(no Codex home)' }
2423	    $fileReason = ''
2424	    if ($Config.Exists -and -not $Config.Ok) { $fileReason = $Config.Reason }
2425	    $top = $null
2426	    if ($Config.Exists -and $Config.Ok) { $top = $Config.Tables[''] }
2427	    $topReason = $fileReason
2428	    if (-not $topReason -and $top -and -not $top.Ok) { $topReason = $top.Reason }
2429	    # An unreadable file cannot rule out a profile: never resolved.
2430	    if ($fileReason) { $notes.Add($fileReason) }
2431	    if ($top) {
2432	        $pf = Get-TomlString -Table $top -Key 'profile'
2433	        if ($pf.Present) {
2434	            if ($pf.Reason) { $notes.Add($pf.Reason) }
2435	            else { $notes.Add("the Codex config selects profile '$($pf.Value)' (line $($pf.Line)); profiles are not supported - a profile can change the provider, the model and the effort behind the bridge") }
2436	        }
2437	    }
2438	    $cfgProvider = $null
2439	    $cfgModel = $null
2440	    if ($top -and -not $topReason) {
2441	        $cfgProvider = Get-TomlString -Table $top -Key 'model_provider'
2442	        $cfgModel = Get-TomlString -Table $top -Key 'model'
2443	    }
2444	
2445	    if ($Provider) {
2446	        $id.Provider = $Provider; $id.ProviderSource = '-Provider'
2447	    } elseif ($topReason) {
2448	        if (-not $notes.Contains($topReason)) { $notes.Add($topReason) }
2449	    } elseif ($cfgProvider -and $cfgProvider.Present) {
2450	        if ($cfgProvider.Reason) { $notes.Add($cfgProvider.Reason) }
2451	        elseif (-not $cfgProvider.Value) { $notes.Add("model_provider at line $($cfgProvider.Line) of $where is empty") }
2452	        else { $id.Provider = $cfgProvider.Value; $id.ProviderSource = 'config' }
2453	    } else {
2454	        $id.Provider = 'openai'; $id.ProviderSource = 'codex default'
2455	    }
2456	
2457	    if ($Model) {
2458	        $id.Model = $Model; $id.ModelSource = '-Model'
2459	    } elseif ($topReason) {
2460	        if (-not $notes.Contains($topReason)) { $notes.Add($topReason) }
2461	    } elseif ($cfgModel -and $cfgModel.Present) {
2462	        if ($cfgModel.Reason) { $notes.Add($cfgModel.Reason) }
2463	        elseif (-not $cfgModel.Value) { $notes.Add("model at line $($cfgModel.Line) of $where is empty") }
2464	        else { $id.Model = $cfgModel.Value; $id.ModelSource = 'config' }
2465	    } elseif ($Config.Exists) {
2466	        $notes.Add("no -Model and no top-level model in $where")
2467	    } else {
2468	        $notes.Add("no -Model and no Codex config at $where (the model Codex picks by default is not known to the bridge)")
2469	    }
2470	
2471	    $compat = ''
2472	    $infos = New-Object System.Collections.Generic.List[string]
2473	    if ($id.ProviderSource) {
2474	        $name = $id.Provider
2475	        $tableName = '[' + (Format-TomlPath @('model_providers', $name)) + ']'
2476	        $err = ''
2477	        $pt = $null
2478	        $setProblem = ''
2479	        if ($Config.Exists -and $Config.Ok) {
2480	            $pt = Get-ProviderTable -Config $Config -Name $name
2481	            $setProblem = Get-ProviderSetProblem -Config $Config -Name $name
2482	        }
2483	        if ($setProblem) {
2484	            # Something the scanner cannot read may declare this provider: neither the
2485	            # built-in fallback nor "unknown provider" can be claimed.
2486	            $err = "the providers in $where could not be established, so $tableName may be declared there - $setProblem"
2487	        } elseif ($name -ceq 'openai' -and -not ($pt -and $pt.Found)) {
2488	            # Built in, no user table. (A config that cannot be scanned is already a
2489	            # note: it cannot rule out a [model_providers.openai] table either.)
2490	            $compat = 'cc-provider-v1|builtin:openai'
2491	            $id.HostName = 'builtin:openai'
2492	            $id.WireApi = '(built in)'
2493	            $display = 'endpoint builtin:openai'
2494	            $pc = New-Object PSObject
2495	            $pc | Add-Member -NotePropertyName 'builtin' -NotePropertyValue 'openai'
2496	            if ($OpenAiBaseUrl -and $OpenAiBaseUrl.Trim()) {
2497	                $cu = ConvertTo-CanonicalBaseUrl $OpenAiBaseUrl
2498	                $audit = ($cu.Url -replace '\?.*$', '?...')
