2591	    param($Identity, [string]$Engine, [string]$Provider, [string]$Model, [string]$Launcher, [string]$Auth = '', $Endpoint = $null)
2592	    $id = $Identity
2593	    $id.Engine = $Engine
2594	    $spec = Get-EngineSpec -Name $Engine
