2600	    $authModes = @(Get-PropertyValue $spec 'AuthModes' @())
2601	    if ($authModes.Count -gt 0) {
2602	        if ($Auth -and $authModes -notcontains $Auth) { $id.Error = "the $Engine engine takes auth $($authModes -join ' or ') (got '$Auth')" }
2603	        if ($null -eq $id.PSObject.Properties['Auth']) { $id | Add-Member -NotePropertyName 'Auth' -NotePropertyValue '' }
2604	        $id.Auth = $(if ($authModes -contains $Auth) { $Auth } else { [string]$authModes[0] })
2605	        if ($null -eq $id.PSObject.Properties['Endpoint']) { $id | Add-Member -NotePropertyName 'Endpoint' -NotePropertyValue $null }
