2620	    $pc | Add-Member -NotePropertyName 'engine' -NotePropertyValue $Engine
2621	    $pc | Add-Member -NotePropertyName 'launcher' -NotePropertyValue $(if ($Launcher) { $Launcher } else { '' })
2622	    # (wave 23) the engine's own fields - muse: credential_mechanism (D4); (wave 29) claude:
2623	    # credential_mechanism (the roster's auth), auth_method, api_provider
2624	    if ($spec.Adapter -and $spec.Adapter.PSObject.Properties['IdentityConfig'] -and $spec.Adapter.IdentityConfig) {
2625	        $icArgs = @{}
