2669	# Per-run Codex config overrides: -CodexConfig and a roster entry's codex_config follow the
2670	# same rules. Each item is key=value; one string may carry several, split only at a comma
2671	# that starts the next key=, so a value like [1,2] stays whole. Keys that would change what
2672	# the ledger records (model, model_provider, profile, model_reasoning_effort,
2673	# model_providers.*) are refused. A value starting with ~/ or ~\ gets the home directory
2674	# ($HOME, else USERPROFILE) and forward slashes (Codex does not expand ~; on Windows
2675	# `~/...` fails with os error 123). A value that is not a TOML literal is wrapped in double
2676	# quotes (Codex parses the value as TOML and falls back to a literal string, so a bare path
2677	# is a TOML string either way). { Items (string[], as passed to codex and recorded in the
2678	# ledger); Error ('' or the message, prefixed by $Label) }.
2679	function ConvertFrom-CodexConfigItems {
2680	    param([string[]]$Values, [string]$Label = '-CodexConfig')
2681	    $items = New-Object System.Collections.Generic.List[string]
2682	    foreach ($cfgArg in @($Values)) {
2683	        if (-not $cfgArg -or -not $cfgArg.Trim()) { continue }
2684	        foreach ($item in ($cfgArg.Trim() -split ',(?=\s*[A-Za-z0-9_.]+=)')) {
2685	            $item = $item.Trim()
2686	            if ($item -notmatch '^[A-Za-z0-9_.]+=.+$') {
2687	                return [pscustomobject]@{ Items = [string[]]@(); Error = "$Label '$item' is malformed: expected key=value (key: letters, digits, _ and .; a non-empty value)." }
2688	            }
2689	            $cfgKey = $item.Substring(0, $item.IndexOf('='))
2690	            $cfgValue = $item.Substring($item.IndexOf('=') + 1)
2691	            if (@('model', 'model_provider', 'profile', 'model_reasoning_effort', 'model_providers') -ccontains $cfgKey -or $cfgKey.StartsWith('model_providers.', [StringComparison]::Ordinal)) {
2692	                return [pscustomobject]@{ Items = [string[]]@(); Error = "$Label '$item' is refused: $cfgKey is part of the reviewer identity and effort the bridge records (use -Model / -Provider / -Effort; providers belong in the Codex config)." }
2693	            }
2694	            if ($cfgValue -match '^~[\\/]') {
2695	                $homeDir = $HOME
2696	                if (-not $homeDir) { $homeDir = $env:USERPROFILE }
2697	                $cfgValue = (($homeDir.TrimEnd([char]'\', [char]'/') + $cfgValue.Substring(1)) -replace '\\', '/')
2698	            }
2699	            if ($cfgValue -notmatch '^(["''0-9\[{]|true$|false$)') { $cfgValue = '"' + (ConvertTo-TomlBasicString $cfgValue) + '"' }
2700	            $items.Add("$cfgKey=$cfgValue")
2701	        }
2702	    }
2703	    return [pscustomobject]@{ Items = [string[]]$items.ToArray(); Error = '' }
2704	}
